mapper.update:
UPDATE activity
SET registration_open = #{open}
WHERE id = #{id}
  AND org_id = #{orgId}

UPDATE activity
SET proposal = #{proposal}
WHERE id = #{id}
  AND org_id = #{orgId}
  AND status = 'DRAFT'

UPDATE activity
SET status = #{toStatus}
WHERE id = #{id}
  AND org_id = #{orgId}
  AND status = #{fromStatus}

UPDATE activity
SET confirmed_at = CURRENT_TIMESTAMP(6)
WHERE id = #{id}
  AND org_id = #{orgId}

UPDATE activity
SET review_note = #{reviewNote},
    submitted_by = #{submittedBy},
    confirmed_by = #{confirmedBy},
    confirm_type = #{confirmType}
WHERE id = #{id}
  AND org_id = #{orgId}

